/**
 * Remark plugin: replaces %%API%% placeholders with auto-generated API docs.
 *
 * Reads the API markdown from the packages/website-astro/api/ directory
 * and injects it into the document AST.
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { fromMarkdown } from 'mdast-util-from-markdown'
import { gfmTable } from 'micromark-extension-gfm-table'
import { gfmTableFromMarkdown } from 'mdast-util-gfm-table'
import { visit } from 'unist-util-visit'

// Deprecated aliases: real doc pages with no interface.ts of their own, so the
// generated API markdown lives under the name they alias.
const aliases = {
  useClickAway: 'useClickOutside',
  useCopyToClipboard: 'useClipboard',
}

// Generated by `pnpm --filter @reactuses/core gend`. Anchored to this file, not
// process.cwd(): astro never chdirs, so a cwd-relative path quietly resolves to
// nothing whenever the build is invoked from outside the package directory —
// and every %%API%% marker on the site would be dropped without an error.
const API_DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../api')

if (!fs.existsSync(API_DIR)) {
  throw new Error(
    `[remark-api-inject] API docs not found at ${API_DIR}. Run \`pnpm --filter @reactuses/core gend\`.`,
  )
}

// Hooks that legitimately have no interface.ts, so `gend` never emits API docs
// for them. Anything else that misses is a stale checkout or a forgotten `gend`.
const NO_API_DOC = new Set([
  'useIsomorphicLayoutEffect',
  'useOnceEffect',
  'useOnceLayoutEffect',
  'useUpdateEffect',
  'useUpdateLayoutEffect',
])
const warned = new Set()

export function remarkApiInject() {
  return (tree, file) => {
    const nodesToReplace = []

    visit(tree, (node, index, parent) => {
      // Match paragraph nodes that contain %%API%%
      if (
        node.type === 'paragraph'
        && node.children?.length === 1
        && node.children[0].type === 'text'
        && node.children[0].value.trim() === '%%API%%'
      ) {
        nodesToReplace.push({ node, index, parent })
      }
    })

    for (const { index, parent } of nodesToReplace.reverse()) {
      // Derive hook name from file path
      const filePath = file.history?.[0] || file.path || ''
      const basename = path.basename(filePath, path.extname(filePath))
      const hookName = aliases[basename] || basename

      // Detect locale from file path
      let localeSuffix = ''
      if (filePath.includes('docs-zh-hans')) {
        localeSuffix = '-zhHans'
      }
      else if (filePath.includes('docs-zh-hant')) {
        localeSuffix = '-zhHant'
      }

      // Read API doc (try locale-specific first, fallback to English)
      let apiPath = path.join(API_DIR, `${hookName}-README${localeSuffix}.md`)
      if (localeSuffix && !fs.existsSync(apiPath)) {
        apiPath = path.join(API_DIR, `${hookName}-README.md`)
      }
      if (!fs.existsSync(apiPath)) {
        if (!NO_API_DOC.has(hookName) && !warned.has(hookName)) {
          warned.add(hookName)
          console.warn(
            `[remark-api-inject] no API doc for ${hookName}; %%API%% dropped. Run \`pnpm --filter @reactuses/core gend\`.`,
          )
        }
        parent.children.splice(index, 1)
        continue
      }

      const apiContent = fs.readFileSync(apiPath, 'utf-8')
      const apiAst = fromMarkdown(apiContent, {
        extensions: [gfmTable()],
        mdastExtensions: [gfmTableFromMarkdown()],
      })

      // Wrap with an "API" heading
      const apiNodes = [
        { type: 'heading', depth: 2, children: [{ type: 'text', value: 'API' }] },
        ...apiAst.children,
      ]

      parent.children.splice(index, 1, ...apiNodes)
    }
  }
}
